            aOrbiterH = ((aOrbiterH + aOrbiterJ) + 0x1D7E56DE621E0A9EULL) + aNonceWordF;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0xBE531EADB6B3B799ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x16E3F1317AD04B0FULL), 21U);
