            aOrbiterJ = (aOrbiterJ + aOrbiterC) + 0x89DB8D2C0D4C20E5ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterJ) ^ 0x248ADB67B01B1D05ULL) ^ aOrbiterUpdateSaltE[((aIndex + 28U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x4B422AE15D33A8BBULL), 35U);
