            aIngress ^= (RotL64(aEarthLaneC[((aIndex + 11082U)) & S_BLOCK1], 58U) ^ RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 16308U)) & S_BLOCK1], 13U));
