            aOrbiterH = ((aOrbiterH ^ aOrbiterA) ^ 0x43A55629E7A39D3AULL) ^ aOrbiterUpdateSaltA[((aIndex + 22U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x0718F890BA3EB171ULL), 57U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0x81924C71F9617998ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterJ) ^ 0x5E95E32BB1F32B9CULL) ^ aOrbiterUpdateSaltB[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x8FBA514829126565ULL), 13U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x15479052B56DDE88ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterF) ^ 0xE8D0CD476D13BA81ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x39AD602AB1774B2BULL), 51U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterF) + 0x68663DC7D011C0BBULL) + aNonceWordG;
            aOrbiterI = ((aOrbiterI ^ aOrbiterH) ^ 0x1D91ECD55045F81DULL) ^ aNonceWordF;
