            aIngress = (RotL64(aHeartLaneA[((aIndex + 11504U)) & S_BLOCK1], 60U) ^ RotL64(aPoisonLaneC[((aIndex + 15868U)) & S_BLOCK1], 43U));
            aIngress ^= (RotL64(aWoodLaneC[((aIndex + 11084U)) & S_BLOCK1], 5U) ^ RotL64(aWindLaneC[((aIndex + 15954U)) & S_BLOCK1], 19U));
            aIngress = TwistMix64::DiffuseB(((aIngress ^ aDomainWordIngress) ^ aNonceWordO));
            //
            aCross = (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 8690U)) & S_BLOCK1], 57U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 9496U)) & S_BLOCK1], 28U));
