            //
            aOrbiterJ = (aOrbiterJ + aOrbiterA) + 0x6E88AA9D146A4E6BULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterJ) ^ 0x88209B94AA0D4CF2ULL) ^ aOrbiterUpdateSaltC[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xA79686E9D9493C9DULL), 27U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x596611238CCB2E3FULL) + aOrbiterUpdateSaltE[((aIndex + 11U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterF) ^ 0x603D8B1F04A76F5EULL) ^ aNonceWordJ;
            aOrbiterI = RotL64((aOrbiterI * 0x89142C4AAF639A35ULL), 13U);
