            aOrbiterF = (aWandererE + RotL64(aPrevious, 47U)) + 0xD0ABE2A20DBC2710ULL;
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0x113A94C3E2EA0875ULL;
