            aOrbiterB = ((aWandererH + RotL64(aCross, 50U)) + RotL64(aCarry, 5U)) + 0xFA1D5B760B4DAA9EULL;
            aOrbiterA = ((aWandererA + RotL64(aPrevious, 35U)) + 0x612A191F02A786D0ULL) + aPhaseAOrbiterAssignSaltA[(((31U - aIndex) + 7U)) & S_SALT1];
