            aOrbiterH = (((aWandererD + RotL64(aPrevious, 57U)) + RotL64(aCarry, 19U)) + 0x8AE812B6162F1E96ULL) + aPhaseAOrbiterAssignSaltB[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterD = ((aWandererC + RotL64(aScatter, 29U)) + RotL64(aCarry, 57U)) + 0xC78B6E02AC5E92BCULL;
            //
            aOrbiterB = ((aOrbiterB + aOrbiterA) + 0x0DD914A567570F72ULL) + aPhaseAOrbiterUpdateSaltF[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterB) ^ 0xC0D03466A7D6C1CFULL;
            aOrbiterG = RotL64((aOrbiterG * 0x5EF16D3BEC0AAF09ULL), 51U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterJ) + 0x1D67181C3F9EE668ULL) + aPhaseAOrbiterUpdateSaltB[((aIndex + 25U)) & S_SALT1];
