            aOrbiterG = (aOrbiterG + aOrbiterI) + 0xF581A0B57BB5EC89ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterG) ^ 0xF14572F3B3906C41ULL) ^ aPhaseAOrbiterUpdateSaltC[((aIndex + 12U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x240BB553168DDBB1ULL), 37U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x494B12B0BC0420C3ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0x78893407DC9515D1ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x1352B0AF39BE6C1BULL), 5U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterG) + 0x6E731A0A681BA02DULL) + aPhaseAOrbiterUpdateSaltD[((aIndex + 13U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0x467BC1318619492CULL;
            aOrbiterH = RotL64((aOrbiterH * 0x69B9205A6A09D12BULL), 11U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0x8B71317712E77892ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0x4AD8C2E99C54F781ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x0DC7A272CAB3A1F5ULL), 23U);
            //
            aIngress = aOrbiterJ ^ RotL64(aOrbiterG, 3U);
            aIngress = aIngress + (RotL64(aOrbiterH, 57U) ^ aOrbiterD);
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterB, 27U));
            aIngress = aIngress + RotL64(aOrbiterA, 47U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererJ = aWandererJ + (((RotL64(aScatter, 41U) + aOrbiterI) + RotL64(aOrbiterB, 39U)) + RotL64(aCarry, 51U));
